// Probe the fixture server and run the streaming POST/ACK flow
const {fetch} = await import("noe:http");

const BASE = "http://127.0.0.1:33433";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const bytes = [0, 255, 17, 34, 128, 0, 255];
let ctrl;
const stream = new ReadableStream({
  start(c) {
    ctrl = c;
    c.enqueue(new Uint8Array([0, 255, 17]));
  },
});

let postSettled = false;
const postPromise = fetch(BASE + "/upload", {
  method: "POST",
  body: stream,
  duplex: "half",
}).then((r) => {
  postSettled = true;
  return r;
}, (e) => {
  postSettled = true;
  throw e;
});

let ackStatus = null;
for (let i = 0; i < 200; i++) {
  let res;
  try {
    res = await fetch(BASE + "/ack");
  } catch (e) {
    console.log("ack attempt error:", String(e && e.message || e));
    await sleep(25);
    continue;
  }
  ackStatus = res.status;
  // drain body if any
  const txt = await res.text().catch(() => "");
  if (ackStatus === 204) {
    console.log("ACK 204 on attempt", i, "postSettled=", postSettled, "body=", JSON.stringify(txt));
    break;
  }
  await sleep(25);
}

if (ackStatus !== 204) {
  console.log("never got 204, last status", ackStatus);
  ctrl.close();
  throw new Error("no ack");
}

ctrl.enqueue(new Uint8Array([34, 128, 0, 255]));
ctrl.close();

const postRes = await postPromise;
const status = postRes.status;
const text = await postRes.text();
console.log("POST status", status, "headers", JSON.stringify([...postRes.headers]));
console.log("POST body", text);

let parsed = null;
try { parsed = JSON.parse(text); } catch {}
console.log("parsed", JSON.stringify(parsed));
console.log("expected bytes", JSON.stringify(bytes));

