// Redo the streaming upload flow and persist report.json in the working directory
const {fetch} = await import("noe:http");
const fs = await import("node:fs");
const path = await import("node:path");

const BASE = "http://127.0.0.1:33433";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const expected = [0, 255, 17, 34, 128, 0, 255];

let ctrl;
const stream = new ReadableStream({
  start(c) {
    ctrl = c;
    c.enqueue(new Uint8Array([0, 255, 17]));
  },
});

let postSettled = false;
const postPromise = fetch(BASE + "/upload", {method: "POST", body: stream, duplex: "half"})
  .finally(() => { postSettled = true; });

let ackStatus = null;
let ackAfterPending = false;
for (let i = 0; i < 200; i++) {
  const res = await fetch(BASE + "/ack");
  await res.arrayBuffer().catch(() => {});
  ackStatus = res.status;
  if (ackStatus === 204) {
    ackAfterPending = !postSettled;
    break;
  }
  await sleep(25);
}
if (ackStatus !== 204) {
  try { ctrl.close(); } catch {}
  throw new Error("ACK never returned 204, last status " + ackStatus);
}

ctrl.enqueue(new Uint8Array([34, 128, 0, 255]));
ctrl.close();

const postRes = await postPromise;
const status = postRes.status;
const parsed = JSON.parse(await postRes.text());

const bytesOk = Array.isArray(parsed.bytes) && parsed.bytes.length === expected.length &&
  parsed.bytes.every((b, i) => b === expected[i]);
const ok = status === 200 && bytesOk && parsed.prefixBeforeEOF === true;

const report = {status, bytes: parsed.bytes, prefixBeforeEOF: parsed.prefixBeforeEOF};
const outPath = path.resolve(process.cwd(), "report.json");
fs.writeFileSync(outPath, JSON.stringify(report, null, 2) + "\n", "utf8");

console.log("ackWhilePostPending:", ackAfterPending);
console.log("status:", status, "bytesOk:", bytesOk, "prefixBeforeEOF:", parsed.prefixBeforeEOF);
console.log("allChecksPass:", ok);
console.log("saved:", outPath);
console.log("fileContent:", fs.readFileSync(outPath, "utf8"));

