// POST a two-phase streamed body to the fixture, then read the echoed response
const {fetch} = await import("noe:http");
const base = "http://127.0.0.1:41897";

let releaseAck;
const ackGate = new Promise((r) => { releaseAck = r; });
let acked = null;

async function waitForAck() {
  const deadline = Date.now() + 15000;
  for (;;) {
    try {
      const res = await fetch(base + "/ack");
      console.log("ack attempt status:", res.status);
      if (res.status === 204) {
        acked = 204;
        releaseAck(204);
        return 204;
      }
      await res.text().catch(() => {});
    } catch (e) {
      console.log("ack attempt error:", String(e && e.message || e));
    }
    if (Date.now() > deadline) throw new Error("ack timeout");
    await new Promise((r) => setTimeout(r, 25));
  }
}

const first = new Uint8Array([0, 255, 17]);
const rest = new Uint8Array([34, 128, 0, 255]);

let sent = false;
