// Test a minimal streamed POST body without gating to isolate the fetch failure
const {fetch} = await import("noe:http");
const base = "http://127.0.0.1:41897";

async function tryPost(label, opts) {
  try {
    const r = await fetch(base + "/upload", opts);
    console.log(label, "->", r.status, await r.text());
  } catch (e) {
    console.log(label, "error:", e && e.message, "| cause:", e && e.cause && (e.cause.message || String(e.cause)));
  }
}

await tryPost("plain-stream-no-duplex", {
  method: "POST",
  body: new ReadableStream({
    start(c) { c.enqueue(new Uint8Array([0,255,17])); c.enqueue(new Uint8Array([34,128,0,255])); c.close(); },
  }),
});

await tryPost("plain-stream-duplex-half", {
  method: "POST",
  body: new ReadableStream({
    start(c) { c.enqueue(new Uint8Array([0,255,17])); c.enqueue(new Uint8Array([34,128,0,255])); c.close(); },
  }),
  duplex: "half",
});

await tryPost("async-delayed-stream", {
  method: "POST",
  body: new ReadableStream({
    async start(c) {
      c.enqueue(new Uint8Array([0,255,17]));
      await new Promise((r) => setTimeout(r, 50));
      c.enqueue(new Uint8Array([34,128,0,255]));
      c.close();
    },
  }),
});

// Retry gated streaming with concurrent ack polling and full error diagnostics
const {fetch} = await import("noe:http");
const base = "http://127.0.0.1:41897";

let log = [];
const t0 = Date.now();
const stamp = (m) => log.push(`${Date.now() - t0}ms ${m}`);

const firstChunk = new Uint8Array([0, 255, 17]);
const restChunk = new Uint8Array([34, 128, 0, 255]);

let releaseAck;
const gate = new Promise((r) => { releaseAck = r; });

async function pollAck() {
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    try {
      const r = await fetch(base + "/ack");
      stamp("ack status " + r.status);
      if (r.status === 204) { releaseAck(true); return true; }
      await r.text().catch(() => {});
    } catch (e) {
      stamp("ack err " + (e && e.message));
    }
    await new Promise((r) => setTimeout(r, 25));
  }
  return false;
}

const stream = new ReadableStream({
  start(c) {
    stamp("start: enqueue first");
    c.enqueue(firstChunk);
    (async () => {
      await gate;
      stamp("gate open: enqueue rest");
      try { c.enqueue(restChunk); c.close(); stamp("closed"); }
      catch (e) { stamp("enqueue err " + e.message); }
    })();
  },
});

const ackP = pollAck().then((ok) => stamp("pollAck done " + ok));

const uploadP = fetch(base + "/upload", {method: "POST", body: stream})
  .then(async (r) => { const t = await r.text(); stamp("upload " + r.status + " " + t); return {ok: true, status: r.status, text: t}; })
  .catch((e) => { stamp("upload ERR " + (e && e.message) + " cause=" + (e && e.cause && (e.cause.message || String(e.cause)))); return {ok: false}; });

const [u] = await Promise.all([uploadP, ackP]);
console.log(log.join("\n"));
console.log("result:", JSON.stringify(u));

// Final run: gated streamed POST, verify 200/bytes/prefixBeforeEOF, write report.json
const {fetch} = await import("noe:http");
const fs = await import("node:fs/promises");
const path = await import("node:path");

const base = "http://127.0.0.1:41897";
const EXPECTED = [0, 255, 17, 34, 128, 0, 255];
const t0 = Date.now();
const log = [];
const note = (m) => log.push(`${Date.now() - t0}ms ${m}`);

// 1) How does /ack look before we start producing anything?
let preAck = "n/a";
try {
  const r = await fetch(base + "/ack");
  preAck = r.status;
  await r.text().catch(() => {});
} catch (e) {
  preAck = "error:" + (e && e.message);
}
note("pre-upload /ack status = " + preAck);

const firstChunk = new Uint8Array(EXPECTED.slice(0, 3));
const restChunk = new Uint8Array(EXPECTED.slice(3));

let ackStatus = null;
let releaseAck;
const gate = new Promise((r) => { releaseAck = r; });
let restEnqueued = false;

async function awaitAck() {
  const deadline = Date.now() + 15000;
  let attempts = 0;
  while (Date.now() < deadline) {
    attempts++;
    try {
      const r = await fetch(base + "/ack");
      note(`ack attempt #${attempts} -> ${r.status}`);
      await r.text().catch(() => {});
      if (r.status === 204) { ackStatus = 204; note("ack 204 received; releasing producer"); releaseAck(true); return; }
    } catch (e) {
      note(`ack attempt #${attempts} error ${e && e.message}`);
    }
    await new Promise((r) => setTimeout(r, 20));
  }
  throw new Error("timed out waiting for ack 204");
}

const stream = new ReadableStream({
  start(controller) {
    note("producing first 3 bytes: " + Array.from(firstChunk).join(","));
    controller.enqueue(firstChunk);
    (async () => {
      try {
        await gate;               // blocks until GET /ack returned 204
        note("producing remaining 4 bytes: " + Array.from(restChunk).join(","));
        restEnqueued = true;
        controller.enqueue(restChunk);
        controller.close();
        note("stream closed");
      } catch (e) {
        try { controller.error(e); } catch (_) {}
      }
    })();
  },
});

const uploadPromise = (async () => {
  try {
    const res = await fetch(base + "/upload", { method: "POST", body: stream });
    const bodyText = await res.text();
    note(`upload response ${res.status}: ${bodyText.trim()}`);
    return { ok: true, status: res.status, bodyText };
  } catch (e) {
    note("upload error: " + (e && e.message) + " | cause: " + (e && e.cause && (e.cause.message || String(e.cause))));
    return { ok: false, error: String((e && e.message) || e) };
  }
})();

const ackPromise = awaitAck().catch((e) => { note("awaitAck failed: " + e.message); });

const [up] = await Promise.all([uploadPromise, ackPromise]);

if (!up.ok) {
  console.log(log.join("\n"));
  throw new Error("upload failed: " + up.error);
}

const payload = JSON.parse(up.bodyText);
const bytes = Array.isArray(payload.bytes) ? payload.bytes : null;
const prefixBeforeEOF = payload.prefixBeforeEOF === true;
const status = up.status;

const bytesMatch = Array.isArray(bytes) && bytes.length === EXPECTED.length && bytes.every((b, i) => b === EXPECTED[i]);
const checks = {
  httpStatus200: status === 200,
  bytesMatch,
  prefixBeforeEOF,
  ackWas204: ackStatus === 204,
  restEnqueuedAfterAck: restEnqueued,
};
note("checks: " + JSON.stringify(checks));

if (!checks.httpStatus200) throw new Error("expected HTTP 200, got " + status);
if (!bytesMatch) throw new Error("bytes mismatch: " + JSON.stringify(bytes));
if (!checks.prefixBeforeEOF) throw new Error("prefixBeforeEOF was not true");
if (!checks.ackWas204) throw new Error("never observed 204 from /ack");
if (!checks.restEnqueuedAfterAck) throw new Error("remaining bytes were not produced after the ack");

const report = { status, bytes, prefixBeforeEOF };
const outPath = path.resolve(process.cwd(), "report.json");
await fs.writeFile(outPath, JSON.stringify(report, null, 2) + "\n", "utf8");

console.log(log.join("\n"));
console.log("report written to:", outPath);
console.log("report.json contents:", await fs.readFile(outPath, "utf8"));
console.log("ALL CHECKS PASSED:", JSON.stringify(checks));
